; blank.asm -- chapter 20: seven loops, in lines the VDP does not draw
; generated by gen20.py
        INCLUDE "msx.inc"
        OUTPUT "blank.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
BOX_EMPTY EQU 1             ; the library's two boxes, characters 1 and 2
BOX_FULL  EQU 2
; 64 bytes of text written with seven loops, 18 to 31 T-states a byte, one
; loop a frame, each started in the line after the frame's signal.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 0
        ld c, 0
        ld hl, l18
        call puts
        ld b, 3
        ld c, 0
        ld hl, l23
        call puts
        ld b, 6
        ld c, 0
        ld hl, l25
        call puts
        ld b, 9
        ld c, 0
        ld hl, l26
        call puts
        ld b, 12
        ld c, 0
        ld hl, l27
        call puts
        ld b, 15
        ld c, 0
        ld hl, l29
        call puts
        ld b, 18
        ld c, 0
        ld hl, l31
        call puts
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E0          ; display on, and the frame's signal on
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; the frame's interrupt
        di
        ld a, ($002B)           ; 14: bit 7 is 1 on a 50 Hz machine
        rla                     ;  5
        jp nc, f18j         ; 11
f185s:  ld de, 3
f185:   dec de
        ld a, d
        or e
        jr nz, f185
        ld c, 0
        nop
        nop
        nop
        nop
        jp f18g             ; 11
f18j:
f186s:  ld de, 3
f186:   dec de
        ld a, d
        or e
        jr nz, f186
        ld c, 0
        ld c, 0
        ld c, 0
        nop
        nop
        nop
f18g:
s18:
        ld hl, text             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $1820        ; 40
        DUP 64
        outi                    ; 18
        EDUP
z18:
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; the frame's interrupt
        di
        ld a, ($002B)           ; 14: bit 7 is 1 on a 50 Hz machine
        rla                     ;  5
        jp nc, f23j         ; 11
