s25:
        ld hl, text             ; 11
        ld c, VDP_DATA          ;  8
        VRAM_WRITE $18E0        ; 40
        DUP 64
        ld a, (hl)              ;  8
        inc l                   ;  5
        out (VDP_DATA), a       ; 12: 25
        EDUP
z25:
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; the frame's interrupt
        di
        ld a, ($002B)           ; 14: bit 7 is 1 on a 50 Hz machine
        rla                     ;  5
        jp nc, f26j         ; 11
f265s:  ld de, 3
f265:   dec de
        ld a, d
